            key: 'proj' + ri,
            d: 'M ' + (padL + 6) + ',' + (padT + plotH * 0.5 - rad * 0.55).toFixed(1) + ' A ' + rad + ',' + rad + ' 0 0 1 ' + (padL + 6) + ',' + (padT + plotH * 0.5 + rad * 0.55).toFixed(1),
            fill: 'none',
